snippet_css:
:root{
  --bg: #FBF8F1;
  --fg: #2E3A44;
  --muted: #5F6B75;
  --surface: #FFFFFF;
  --border: #E2DCD0;
  --accent: #7FB3D5;
  --accent-fg: #12303F;
  --focus-ring: #2F6E8F;
  --radius: 14px;
  --radius-sm: 10px;
  --shadow: 0 8px 18px rgba(80,100,120,.14);
  --btn-shadow: none;
  --art-bg: radial-gradient(circle at 30% 25%,#F4D35E,#7FB3D5);
  --media-bg: radial-gradient(circle at 30% 25%,#F4D35E,#A3C585);
  --cta-bg: #F1EAE0;
  --input-bg: #FFFFFF;
  --ok: #6FA37A;
  --warn: #C4573F;
  --font-display: Fraunces,'DM Serif Display',serif;
  --font-body: 'DM Sans','Noto Sans TC',sans-serif;
}

